---@return table translations
function GetWeaponSkinTranslations()
    local language = string.lower(lang or "pt-br")
    language = gWeaponSkinLanguageAliases[language] or language

    return gWeaponSkinTranslations[language] or gWeaponSkinTranslations["pt-br"]
end
